 "content": "def transform(grid):
    """Paint every translated copy of the marked local pattern, where the
    background value is the most frequent non-marker value in the grid."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 2)
    background = counts.most_common(1)[0][0]
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    if not pts:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    pattern = {(r-r0, c-c0) for r, c in pts}
    out = [row[:] for row in grid]
    for top in range(h-(r1-r0+1)+1):
        for left in range(w-(c1-c0+1)+1):
            for dr, dc in pattern:
                r, c = top+dr, left+dc
                if grid[r][c] == background:
                    out[r][c] = 2
    return out
